function canModule(string $module,bool $manage=false):bool{
 if(isAdmin())return true;
 $permissions=$_SESSION['user']['permissions']??[];
 if(!$permissions)return !$manage;
 return !empty($permissions[$module][$manage?'manage':'view']);
}
