function replaceCharge(PDO $db,int $projectId,int $newChargeId,array $types,string $quoteCategory='general',string $currency='ARS'):void{
 $marks=implode(',',array_fill(0,count($types),'?'));
 $s=$db->prepare("SELECT c.id FROM charges c LEFT JOIN quotes q ON q.id=c.quote_id WHERE c.project_id=? AND c.active=1 AND c.id<>? AND c.type IN ($marks) AND COALESCE(q.quote_category,'general')=? AND c.currency=?");
 $s->execute(array_merge([$projectId,$newChargeId],$types,[$quoteCategory,$currency]));
 foreach($s as $old){
  $als=$db->prepare('SELECT payment_id,amount FROM allocations WHERE charge_id=?');$als->execute([$old['id']]);
  foreach($als as $al)$db->prepare('INSERT INTO allocations(payment_id,charge_id,amount) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount=amount+VALUES(amount)')->execute([$al['payment_id'],$newChargeId,$al['amount']]);
  $db->prepare('DELETE FROM allocations WHERE charge_id=?')->execute([$old['id']]);
  $db->prepare('UPDATE charges SET active=0 WHERE id=?')->execute([$old['id']]);
 }
}
function projectFinancialTotals(array $quotes,array $charges,array $payments):array{
 $totals=[];foreach(['ARS','USD'] as $cur)$totals[$cur]=['project_total'=>0.0,'paid'=>0.0,'due_now'=>0.0,'materials'=>0.0,'materials_input'=>0.0,'materials_vat'=>0.0,'materials_paid'=>0.0,'materials_tax'=>[],'labor'=>0.0,'labor_input'=>0.0,'labor_vat'=>0.0,'labor_paid'=>0.0,'labor_tax'=>[],'other'=>0.0];
 $currentQuotes=[];foreach($quotes as $quote){if(!in_array($quote['status'],['aprobado_inicial','final'],true))continue;$key=($quote['quote_category']??'general').'|'.$quote['currency'];if(!isset($currentQuotes[$key]))$currentQuotes[$key]=$quote;}
 $taxLabels=['sin_iva'=>'Sin IVA','iva_incluido'=>'IVA incluido','mas_iva'=>'Más IVA'];
 foreach($currentQuotes as $quote){$cur=$quote['currency'];$materialsMode=$quote['materials_tax_mode']??$quote['tax_mode'];$laborMode=$quote['labor_tax_mode']??$quote['tax_mode'];$materialsRate=(float)($quote['materials_vat_rate']??$quote['vat_rate']);$laborRate=(float)($quote['labor_vat_rate']??$quote['vat_rate']);$materialsInput=(float)$quote['materials_amount'];$laborInput=(float)$quote['labor_amount'];$materialsVat=$materialsMode==='mas_iva'?round($materialsInput*$materialsRate/100,2):0.0;$laborVat=$laborMode==='mas_iva'?round($laborInput*$laborRate/100,2):0.0;$materialsTotal=$materialsInput+$materialsVat;$laborTotal=$laborInput+$laborVat;$totals[$cur]['materials_input']+=$materialsInput;$totals[$cur]['materials_vat']+=$materialsVat;$totals[$cur]['materials']+=$materialsTotal;$totals[$cur]['labor_input']+=$laborInput;$totals[$cur]['labor_vat']+=$laborVat;$totals[$cur]['labor']+=$laborTotal;$totals[$cur]['project_total']+=$materialsTotal+$laborTotal;$materialsTax=($taxLabels[$materialsMode]??$materialsMode).($materialsMode==='mas_iva'?' '.number_format($materialsRate,2,',','.').'%':'');$laborTax=($taxLabels[$laborMode]??$laborMode).($laborMode==='mas_iva'?' '.number_format($laborRate,2,',','.').'%':'');$totals[$cur]['materials_tax'][$materialsTax]=true;$totals[$cur]['labor_tax'][$laborTax]=true;}
 foreach($charges as $charge){if(!$charge['active'])continue;$cur=$charge['currency'];$totals[$cur]['due_now']+=max(0,(float)$charge['amount']-(float)($charge['paid']??0));if($charge['type']==='materiales')$totals[$cur]['materials_paid']+=(float)($charge['paid']??0);elseif(in_array($charge['type'],['ingenieria','mano_obra'],true))$totals[$cur]['labor_paid']+=(float)($charge['paid']??0);if(empty($charge['quote_id'])){$amount=(float)$charge['amount'];$totals[$cur]['project_total']+=$amount;if($charge['type']==='materiales'){$totals[$cur]['materials']+=$amount;$totals[$cur]['materials_input']+=$amount;$totals[$cur]['materials_tax']['Cargo manual']=true;}elseif(in_array($charge['type'],['ingenieria','mano_obra'],true)){$totals[$cur]['labor']+=$amount;$totals[$cur]['labor_input']+=$amount;$totals[$cur]['labor_tax']['Cargo manual']=true;}else $totals[$cur]['other']+=$amount;}}
 foreach($payments as $payment)$totals[$payment['currency']]['paid']+=(float)$payment['amount'];return $totals;
}
