<div class="actions"><div style="flex:1"><span class="muted"><?=e($p['business_name'])?><?php if($p['partner_name']):?> · <?=e($p['partner_name'])?><?php endif;?></span><h1><?=e($p['project_number'])?> · <?=e($p['name'])?></h1></div><?php if(canModule("projects",true)):?><a class="btn light" href="?a=edit_project&id=<?=$id?>">Editar proyecto</a><?php endif;?><span class="pill"><?=e($p['status'])?></span></div><?php foreach(['ARS','USD'] as $cur):if($totals[$cur]['project_total']<.009&&$totals[$cur]['paid']<.009&&$totals[$cur]['due_now']<.009)continue;$projectBalance=$totals[$cur]['project_total']-$totals[$cur]['paid'];?><h2><?=e($cur)?></h2><div class="grid"><div class="card c4"><span class="muted">Valor aprobado del proyecto</span><div class="kpi"><?=mon($totals[$cur]['project_total'],$cur)?></div></div><div class="card c4"><span class="muted">Pagado por el cliente</span><div class="kpi ok"><?=mon($totals[$cur]['paid'],$cur)?></div></div><div class="card c4"><span class="muted"><?=$projectBalance>=0?'Saldo total pendiente':'Saldo a favor del cliente'?></span><div class="kpi <?=$projectBalance>=0?'bad':'ok'?>"><?=mon(abs($projectBalance),$cur)?></div></div></div><div class="card"><div class="actions"><div style="flex:1"><h3 style="margin:0">Detalle del saldo</h3><p class="muted" style="margin:5px 0 0">El pago de ingeniería se descuenta de Mano de obra.</p></div><div><span class="muted">Exigible ahora</span><div class="kpi"><?=mon($totals[$cur]['due_now'],$cur)?></div></div></div><div class="grid" style="margin-top:18px"><div class="c6"><h3>Materiales</h3><p><span class="muted">Condición:</span> <?=e(implode(' · ',array_keys($totals[$cur]['materials_tax']))?:'—')?><br>Importe presupuestado: <b><?=mon($totals[$cur]['materials_input'],$cur)?></b><br>IVA agregado: <b><?=mon($totals[$cur]['materials_vat'],$cur)?></b><br>Total con tratamiento de IVA: <b><?=mon($totals[$cur]['materials'],$cur)?></b><br>Pagado aplicado: <span class="ok"><?=mon($totals[$cur]['materials_paid'],$cur)?></span><br>Saldo de materiales: <b class="bad"><?=mon(max(0,$totals[$cur]['materials']-$totals[$cur]['materials_paid']),$cur)?></b></p></div><div class="c6"><h3>Mano de obra e ingeniería</h3><p><span class="muted">Condición:</span> <?=e(implode(' · ',array_keys($totals[$cur]['labor_tax']))?:'—')?><br>Importe presupuestado: <b><?=mon($totals[$cur]['labor_input'],$cur)?></b><br>IVA agregado: <b><?=mon($totals[$cur]['labor_vat'],$cur)?></b><br>Total con tratamiento de IVA: <b><?=mon($totals[$cur]['labor'],$cur)?></b><br>Pagado aplicado (incluye ingeniería): <span class="ok"><?=mon($totals[$cur]['labor_paid'],$cur)?></span><br>Saldo de mano de obra: <b class="bad"><?=mon(max(0,$totals[$cur]['labor']-$totals[$cur]['labor_paid']),$cur)?></b></p></div><?php if($totals[$cur]['other']>.009):?><div class="c12"><b>Otros cargos:</b> <?=mon($totals[$cur]['other'],$cur)?></div><?php endif;?></div></div><?php endforeach;?>
