<p class="c12"><label>Notas</label><textarea name="notes"></textarea></p></div><h3>Asignación del pago</h3><p class="muted">Indicá cuánto corresponde a cada concepto de la moneda seleccionada.</p><table><tr><th>Concepto</th><th class="right">Pendiente</th><th>Monto a asignar</th></tr><?php foreach($charges as $c):$due=$c['amount']-$c['paid'];?><tr class="charge-row" data-currency="<?=e($c['currency'])?>"><td><span class="pill"><?=e($c['type'])?></span> <?=e($c['description'])?></td><td class="right"><?=mon($due,$c['currency'])?></td><td style="width:200px"><input class="allocation" type="number" min="0" max="<?=$due?>" step=".01" name="alloc[<?=$c['id']?>]" value="0"></td></tr><?php endforeach;?></table><br><button class="btn">Guardar pago y generar recibo</button></form><script>function filterCharges(){const cur=document.getElementById('payment-currency').value;document.querySelectorAll('.charge-row').forEach(row=>{const show=row.dataset.currency===cur;row.style.display=show?'':'none';if(!show)row.querySelector('.allocation').value=0;});}filterCharges();</script></div>
<?php }elseif(in_array($a,['users','edit_profile'],true)&&isAdmin()){$areaLabels=['comercial'=>'Comercial','tecnico'=>'Técnico','administracion'=>'Administración','gerencial'=>'Gerencial'];$profiles=$db->query("SELECT up.*,COUNT(DISTINCT u.id) users_count FROM user_profiles up LEFT JOIN users u ON u.profile_id=up.id GROUP BY up.id ORDER BY up.area,up.name")->fetchAll();$users=$db->query('SELECT u.*,up.name profile_name,up.area profile_area FROM users u LEFT JOIN user_profiles up ON up.id=u.profile_id ORDER BY u.name')->fetchAll();$editing=null;$editingPermissions=[];if($a==='edit_profile'){$s=$db->prepare('SELECT * FROM user_profiles WHERE id=?');$s->execute([(int)($_GET['id']??0)]);$editing=$s->fetch();if(!$editing){echo 'Perfil inexistente.';bottom();exit;}$s=$db->prepare('SELECT * FROM profile_module_permissions WHERE profile_id=?');$s->execute([$editing['id']]);foreach($s as $permission)$editingPermissions[$permission['module_key']]=$permission;}?><div class="actions"><div style="flex:1"><span class="muted">Administración de accesos</span><h1>Perfiles y usuarios</h1></div></div><div class="grid"><div class="card c7"><h2>Perfiles</h2><p class="muted">Cada perfil pertenece a un área y define qué módulos puede ver o gestionar.</p><div class="scroll"><table><tr><th>Perfil</th><th>Área</th><th>Usuarios</th><th></th></tr><?php foreach($profiles as $profile):?><tr><td><b><?=e($profile['name'])?></b></td><td><span class="pill"><?=e($areaLabels[$profile['area']]??$profile['area'])?></span></td><td><?=$profile['users_count']?></td><td><a class="btn light" href="?a=edit_profile&id=<?=$profile['id']?>">Editar permisos</a></td></tr><?php endforeach;?></table><?php if(!$profiles):?><p class="muted">Todavía no hay perfiles creados.</p><?php endif;?></div></div><div class="card c5"><h2><?=$editing?'Editar perfil':'Nuevo perfil'?></h2><form method="post" action="?a=<?=$editing?'update_profile':'save_profile'?>"><?=token()?><?php if($editing):?><input type="hidden" name="profile_id" value="<?=$editing['id']?>"><?php endif;?><p><label>Nombre del perfil</label><input name="name" value="<?=e($editing['name']??'')?>" placeholder="Ej.: Comercial de ventas" required></p><p><label>Área</label><select name="area" required><option value="">Seleccionar…</option><?php foreach($areaLabels as $value=>$label):?><option value="<?=$value?>" <?=($editing['area']??'')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></p><div class="scroll"><table><tr><th>Módulo</th><th>Ver</th><th>Gestionar</th></tr><?php foreach(moduleCatalog() as $moduleKey=>$moduleName):$permission=$editingPermissions[$moduleKey]??null;?><tr><td><?=e($moduleName)?></td><td><input type="checkbox" name="permissions[<?=$moduleKey?>][view]" value="1" <?=$permission&&$permission['can_view']?'checked':''?>></td><td><input type="checkbox" name="permissions[<?=$moduleKey?>][manage]" value="1" <?=$permission&&$permission['can_manage']?'checked':''?> <?=$moduleKey==='billing'?'disabled':''?>></td></tr><?php endforeach;?></table></div><br><div class="actions"><button class="btn"><?=$editing?'Guardar cambios':'Crear perfil'?></button><?php if($editing):?><a class="btn light" href="?a=users">Cancelar</a><?php endif;?></div></form></div></div><div class="grid"><div class="card c8"><h2>Usuarios</h2><div class="scroll"><table><tr><th>Nombre</th><th>Email</th><th>Tipo</th><th>Área / perfil</th><th>Estado</th></tr><?php foreach($users as $u):?><tr><td><b><?=e($u['name'])?></b></td><td><?=e($u['email'])?></td><td><?=e($u['role']==='admin'?'Administrador':'Usuario')?></td><td><?=$u['role']==='admin'?'Acceso total':e(($areaLabels[$u['profile_area']]??'Sin área').' · '.($u['profile_name']??'Sin perfil'))?></td><td><span class="pill"><?=$u['active']?'Activo':'Inactivo'?></span></td></tr><?php endforeach;?></table></div></div><div class="card c4"><h2>Nuevo usuario</h2><form method="post" action="?a=save_user"><?=token()?><p><label>Nombre</label><input name="name" required></p><p><label>Email</label><input type="email" name="email" required></p><p><label>Clave</label><input type="password" minlength="8" name="password" required></p><p><label>Tipo de usuario</label><select name="role" id="user-role" onchange="toggleUserProfile()"><option value="consulta">Usuario con perfil</option><option value="admin">Administrador (acceso total)</option></select></p><p id="profile-field"><label>Perfil</label><select name="profile_id"><option value="">Seleccionar…</option><?php foreach($profiles as $profile):?><option value="<?=$profile['id']?>"><?=e($areaLabels[$profile['area']]??$profile['area'])?> · <?=e($profile['name'])?></option><?php endforeach;?></select></p><button class="btn">Crear usuario</button></form><script>function toggleUserProfile(){document.getElementById('profile-field').style.display=document.getElementById('user-role').value==='admin'?'none':''}toggleUserProfile()</script></div></div><?php }
bottom();
